        // Convert to unsigned Long for correct comparison
        val uip = ip.toLong() and 0xFFFFFFFFL
        var lo = 0
        var hi = starts.size - 1
        while (lo <= hi) {
            val mid = (lo + hi) ushr 1
            val uStart = starts[mid].toLong() and 0xFFFFFFFFL
            val uEnd = ends[mid].toLong() and 0xFFFFFFFFL
            when {
                uip < uStart -> hi = mid - 1
                uip > uEnd -> lo = mid + 1
                else -> return true
            }
        }
        return false
    }

    /**
     * Convert all ranges to CIDR notation strings for sing-box rule_set.
     * Each [start, end] range is decomposed into minimal covering CIDRs.
     */
    fun allCidrs(): List<String> {
        val result = mutableListOf<String>()
        for (i in starts.indices) {
            val s = starts[i].toLong() and 0xFFFFFFFFL
            val e = ends[i].toLong() and 0xFFFFFFFFL
            rangeToCidrs(s, e, result)
        }
        return result
    }

    private fun rangeToCidrs(start: Long, end: Long, out: MutableList<String>) {
        var current = start
        while (current <= end) {
            // Find the largest CIDR block starting at 'current' that fits within [current, end]
            val maxBits = java.lang.Long.numberOfTrailingZeros(current).coerceAtMost(32)
            var bits = maxBits
            while (bits > 0) {
                val blockEnd = current + (1L shl bits) - 1
                if (blockEnd <= end) break
                bits--
            }
            val prefix = 32 - bits
            out.add("${(current shr 24) and 0xFF}.${(current shr 16) and 0xFF}.${(current shr 8) and 0xFF}.${current and 0xFF}/$prefix")
            current += (1L shl bits)
        }
    }
}
